head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > accessibility]<br/>컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "미설정 시 InputCalendar 컴포넌트에 웹접근성 지원 기능을 적용하지 않습니다.",
        "true 설정 시 InputCalendar 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용합니다.",
        "true 설정 시 placeholder 속성에 calendarValueType 속성에 맞게 'yyyy{d}MM{d}dd HH:mm:SS' 값이 설정됩니다. ('{d}'는 delimiter 속성값)",
        "true 설정 시 renderType='component', renderDiv='true', focusOnOutDiv=true, cancelButtonShow='true' 가 설정됩니다.",
        "true 설정 시 컴포넌트의 버튼 영역이 a 태그로 렌더링됩니다.",
        "true 설정 시 팝업 달력의 요일 영역을 th 태그의 한자리 한글('일','월') 텍스트로 렌더링 합니다.",
        "true 설정 시 팝업 달력에서 날짜 영역의 table, tr, th, td 태그에 role 속성을 'grid', 'row', 'columnheader', 'gridcell' 로 설정합니다.",
        "true 설정 시 팝업 달력의 선택일에 aria-selected='rue' 를 설정합니다.",        
        "false 설정 시 InputCalendar 컴포넌트에 웹접근성 지원 기능을 적용하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),        
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createBasicInputCalendar(cList, eList); 
}



scwin.getOptions = function () {
    let rtn = ''

    rtn = target1.options.placeholder;
    wf_body_bottom.getObj("scwin").setReturnValue("placeHolder : " + rtn);

    rtn = target1.options.renderType;
    wf_body_bottom.getObj("scwin").setReturnValue("renderType : " + rtn);

    rtn = target1.options.renderDiv;
    wf_body_bottom.getObj("scwin").setReturnValue("renderDiv : " + rtn);

    rtn = target1.options.focusOnOuterDiv;
    wf_body_bottom.getObj("scwin").setReturnValue("focusOnOutDiv : " + rtn);

    rtn = target1.options.cancelButtonShow;
    wf_body_bottom.getObj("scwin").setReturnValue("cancelButtonShow : " + rtn);
}


scwin.getButtonInfo = function () {
    let aElement = document.querySelector('a[id*="target1_img"]')

    if (aElement)
        wf_body_bottom.getObj("scwin").setReturnValue("button tagName : " + aElement.tagName);
}



scwin.getWeekInfo = function () {
    let weekElement = document.querySelector('th[class*="w2calendar_col_day_text w2calendar_day_text_0"]');

    if (weekElement)
        wf_body_bottom.getObj("scwin").setReturnValue("week tagName : " + weekElement.tagName + ", text : " + weekElement.textContent);
}



scwin.getDayInfo = function () {
    let popupCalendarElement = document.querySelector('div[id*="target1_calendar"]');

    if (popupCalendarElement) {
        let tableElement = popupCalendarElement.querySelector('table');
        let trElement = popupCalendarElement.querySelector('tr');
        let thElement = popupCalendarElement.querySelector('th');
        let tdElement = popupCalendarElement.querySelector('td');
        let selectedDayElement = popupCalendarElement.querySelector('td[class*="w2calendar_selected"]');

        if (tableElement)
            wf_body_bottom.getObj("scwin").setReturnValue("table role : " + tableElement.role);

        if (trElement)
            wf_body_bottom.getObj("scwin").setReturnValue("tr role : " + trElement.role);

        if (thElement)
            wf_body_bottom.getObj("scwin").setReturnValue("th role : " + thElement.role);

        if (tdElement)
            wf_body_bottom.getObj("scwin").setReturnValue("td role : " + tdElement.role);

        if (selectedDayElement)
            wf_body_bottom.getObj("scwin").setReturnValue("ariaSelected : " + selectedDayElement.ariaSelected);
    }
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getOptions();
        scwin.getButtonInfo();
        scwin.getWeekInfo();
        scwin.getDayInfo();
    }, 100);    
}
